    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_route PRIMARY KEY (id),
    CONSTRAINT uq_route_id_tenant UNIQUE (id, tenant_id)
);
COMMENT ON TABLE transport.route IS 'Transport route served by a vehicle.';
COMMENT ON COLUMN transport.route.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN transport.route.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN transport.route.institution_id IS 'Institution.';
COMMENT ON COLUMN transport.route.academic_year_id IS 'Year the route runs.';
COMMENT ON COLUMN transport.route.name IS 'Route name.';
